(function() {
  'use strict';
  const M=window.VAGuided, $=id=>document.getElementById(id), app=$('app');
  const S={identity:null,token:null,rounds:[],round:null,book:null,mode:null,target:null,draft:null,art:null,step:0,screen:'home',teacher:null,overview:null,detail:null,epoch:0,options:[],storageError:false,conflict:null,upload:null,filter:'all'};
  let messageTimer;
  const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const siteBase=()=>{if(window.VA_BASE)return window.VA_BASE;const b=document.querySelector('base');if(b&&b.getAttribute('href')){try{const u=new URL(b.getAttribute('href'),location.href);let p=u.pathname||'/';return p.endsWith('/')?p:(p+'/');}catch(_){}}if(/\.github\.io$/i.test(location.hostname)){const segs=location.pathname.split('/').filter(Boolean);if(segs.length&&segs[0]!=='assets')return '/'+segs[0]+'/';}let p=location.pathname||'/';if(/\/assets\//.test(p)){const segs=p.split('/').filter(Boolean);const i=segs.indexOf('assets');if(i>0)return '/'+segs.slice(0,i).join('/')+'/';p=p.replace(/\/assets\/.*$/,'/');}else if(/\.[a-zA-Z0-9]+$/.test(p))p=p.replace(/\/[^/]+$/,'/');else if(!p.endsWith('/'))p=(p.replace(/\/[^/]*$/,'/')||'/');return p.endsWith('/')?p:p+'/';};
  const withBase=p=>{if(!p||typeof p!=='string')return p;if(/^(?:[a-z]+:)?\/\//i.test(p)||p.startsWith('data:')||p.startsWith('blob:'))return p;const base=siteBase();if(typeof window.VA_withBase==='function')return window.VA_withBase(p);return p.startsWith('/')?base.replace(/\/$/,'')+p:base+p;};
  const asset=p=>(window.VA_ASSETS||{})[p]||withBase(p);
  const icon=(name)=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+({arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',note:'<path d="M6 3h13v18H6zM3 7h5M3 12h5M3 17h5m8-9h5m-5 4h5"/>',save:'<path d="M5 3h13l3 3v15H3V3Zm3 0v6h8V3M7 21v-8h10v8"/>',help:'<path d="M4 4h16v12H10l-6 5V4Z"/><path d="M10 8c0-3 5-3 5 0 0 2-3 2-3 4m0 2v.1"/>',expand:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6m-3-3v6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',refresh:'<path d="M20 7V2l-3 3a8 8 0 1 0 3 10M20 7h-5"/>',check:'<path d="m5 12 4 4L20 5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>'}[name]||'')+'</svg>';
  const button=(text,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
  const portrait=(boy=false)=>`<span class="portrait${boy?' boy':''}" role="img" aria-label="${boy?'小志':'小蓮'}"></span>`;
  const date=v=>v?new Date(v).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
  const latest=arr=>{const by={};(arr||[]).forEach(x=>by[x.id]=x);return Object.values(by);};
  const titleMode=mode=>M.modes[mode];
  function message(text,error=false){clearTimeout(messageTimer);$('message').textContent=text;$('message').classList.toggle('error',error);messageTimer=setTimeout(()=>{$('message').textContent='';},error?12000:5500);}
  function setView(html){app.innerHTML=html;app.classList.toggle('ks1',!!S.round&&S.round.plan.ks==='ks1');document.body.classList.remove('typing');header();}
  function loading(text='正在讀取…'){setView(`<div class="loading"><span class="spinner"></span>${esc(text)}</div>`);}
  function header(){
    $('nav').innerHTML=S.teacher?button('我的班別','teacher-home','','active'):S.identity?button('我的課堂','rounds','',''+(S.screen==='rounds'||S.screen==='lesson'?'active':''))+button('我的筆記','notebooks','',''+(S.screen==='notebooks'||S.screen==='notebook'?'active':'')):'';
    $('identity').innerHTML=S.teacher?`教師 ${button('返回學生入口','logout','','quiet small')}`:S.identity?`${esc(S.identity.classId)}・${esc(S.identity.studentId)}號 ${button('離開','logout','','quiet small')}`:'';
    $('teacher-entry').hidden=!!S.teacher;
  }
  async function api(action,payload={},requestId){
    const epoch=S.epoch,body={schemaVersion:2,action,payload,token:S.token,requestId};
    let result;
    if(window.google&&google.script&&google.script.run){result=await new Promise((resolve,reject)=>google.script.run.withSuccessHandler(resolve).withFailureHandler(reject).callApi(body));}
    else if(window.VA_PREVIEW===true){const response=await fetch('/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('暫時未能連接，請保留內容後再試。');result=await response.json();}
    else throw new Error('請從學校提供的藝言堂・時間膠囊入口開啟。這份檔案沒有接上學校服務。');
    if(epoch!==S.epoch){const e=new Error('畫面已改變');e.code='STALE';throw e;}
    if(!result||!result.ok){const e=new Error(result&&result.error&&result.error.message||'未能完成操作，請保留內容後再試。');e.code=result&&result.error&&result.error.code;if(e.code==='TOKEN_EXPIRED'||e.code==='AUTH_REQUIRED'){persist();showSessionLogin();}throw e;}
    return result.data;
  }
  async function act(fn,element){if(element&&element.disabled)return;const buttons=[...document.querySelectorAll('button:not(:disabled)')];buttons.forEach(b=>b.disabled=true);app.setAttribute('aria-busy','true');try{await fn();}catch(e){if(e.code!=='STALE')message(e.message||'未能完成操作，請保留內容後再試。',true);}finally{buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});app.removeAttribute('aria-busy');}}
  function storageKey(){return S.identity&&S.round&&S.mode&&S.target?'art-time-capsule-v2:'+M.key(S.identity,S.round.id,S.mode,S.target):null;}
  function readStorage(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch(_){return null;}}
  function persist(){if(S.viewRevision)return true;const key=storageKey();if(!S.draft||!key)return !S.storageError;try{localStorage.setItem(key,JSON.stringify(S.draft));S.storageError=false;$('storage-recovery')?.remove();setSaveLabel();return true;}catch(_){S.storageError=true;if(!$('storage-recovery'))app.insertAdjacentHTML('afterbegin',`<div id="storage-recovery" class="notice error" role="alert">這部裝置未能儲存。請先儲存到學校或下載副本。<div class="actions">${button('儲存筆記','save-draft')}${button('下載本機副本','export')}</div></div>`);setSaveLabel('這部裝置未能儲存。請保留此頁，儲存到學校或下載本機副本。');message('本機儲存空間不足，請先儲存到學校或下載本機副本。',true);return false;}}
  function changed(){S.draft.dirty=true;S.draft.modifiedAt=new Date().toISOString();persist();}
  function setSaveLabel(text){const el=$('save-label');if(!el)return;el.textContent=text||(S.draft&&S.draft.dirty?'已存於這部裝置・未儲存到學校':S.draft&&S.draft.baseRevision?(S.draft.serverStatus==='submitted'?'已交給老師':'已儲存到學校'):'這份筆記尚未儲存到學校');}
  function canLeave(){if(!persist()&&(S.draft?.dirty||!S.draft?.baseRevision))return false;if(S.feedbackDirty&&!confirm('教師回饋尚未儲存，要離開並放棄這次輸入嗎？'))return false;S.feedbackDirty=false;return true;}
  function questions(){return S.round.plan.questions[S.mode];}
  function answer(){const id=questions()[S.step].id;return S.draft.responses[id]||(S.draft.responses[id]=M.emptyAnswer());}
  function readonly(){return S.round&&S.round.phase==='closed'||!!S.viewRevision;}
  function cleanDraft(record){return {baseRevision:record?record.revision:0,serverStatus:record?record.status:'',serverId:record?record.id:null,responses:M.clone(record?record.responses:{}),feeling:record?record.feeling||'':'',dirty:false,hintOpen:{},modifiedAt:record?record.updatedAt:''};}
  function subjectRecords(){return (S.book&&S.book.assessments||[]).filter(x=>x.mode===S.mode&&x.targetId===S.target);}
  function localSummary(responses){return questions().map(q=>`${q.label}：${(responses[q.id]||{}).text||((responses[q.id]||{}).support==='oral'?'待口頭回應':(responses[q.id]||{}).support==='help'?'需要協助':'未填')}`).join('\n\n');}
  function exportLocal(){if(!S.draft)return;const blob=new Blob([JSON.stringify({identity:S.identity,roundId:S.round.id,mode:S.mode,targetId:S.target,draft:S.draft},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`藝言堂・時間膠囊-${S.identity.classId}-${S.identity.studentId}-本機副本.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('已下載本機副本。');}
  function loginForm(prefix='login'){const current=S.identity;return `<form id="${prefix}-form" class="login-box" data-form="login" data-prefix="${prefix}"><div class="login-fields"><label class="field"><span>班別</span><select id="${prefix}-class" data-change="login-class" data-prefix="${prefix}" required>${S.options.map(c=>`<option value="${esc(c.classId)}" ${current&&current.classId===c.classId?'selected':''}>${esc(c.classId)}</option>`).join('')}</select></label><label class="field"><span>學號</span><select id="${prefix}-student" required></select></label></div><button type="submit" class="primary round">開始我的探索 ${icon('arrow')}</button></form>`;}
  function updateSeats(prefix){const c=S.options.find(c=>c.classId===$(`${prefix}-class`).value);$(`${prefix}-student`).innerHTML=(c?c.studentIds:[]).map(id=>`<option value="${esc(id)}" ${S.identity&&S.identity.classId===c.classId&&S.identity.studentId===id?'selected':''}>${esc(id)} 號</option>`).join('');}
  function home(error=''){
    S.screen='home';setView(`<section class="hero"><div class="hero-copy"><p class="eyebrow">看見・感受・說出來</p><h1>今天，<br>打開<span class="mark">時間膠囊。</span></h1><p>每個人都可以有不同的發現。<br>跟着小蓮、小志，說出你眼中的藝術。</p>${error?`<div class="notice error">${esc(error)}</div>${button('重新連接','boot','','primary')}`:S.options.length?loginForm():`<div class="notice">學校尚未提供可用班別，請聯絡老師。</div>`}<div class="hero-foot"><span>① 看見細節</span><span>② 說出想法</span><span>③ 留下自己的筆記</span></div></div><div class="hero-art"><div class="painting"><img src="${asset('assets/guided/mona-lisa.jpg')}" alt="達文西《蒙羅麗莎》"></div><span class="hero-message">一幅畫，可以有很多種說法。</span>${portrait()}${portrait(true)}<p class="caption">達文西《蒙羅麗莎》・羅浮宮藏品</p></div></section><div class="guide-strip">${portrait(true)}<div><h3>藝術，從好奇開始。</h3><p class="muted">看一看、指一指，再用自己的話說說。不需要一開始就有完整答案。</p></div></div>`);if(S.options.length&&!error)updateSeats('login');
  }
  async function boot(){try{if(window.VA_PREVIEW)$('demo-banner').hidden=false;const data=await api('loginOptions');S.options=data.classes;home();}catch(e){home(e.message);}}
  async function login(prefix){const classId=$(`${prefix}-class`).value,studentId=$(`${prefix}-student`).value;const old=S.identity;const data=await api('login',{classId,studentId});S.identity={schoolYear:data.schoolYear,classId:data.classId,studentId:data.studentId,grade:data.grade};S.token=data.token;S.teacher=null;S.epoch++;
    if($('session-dialog').open){$('session-dialog').close();if(old&&old.classId===classId&&old.studentId===studentId&&old.schoolYear===data.schoolYear){header();message('已重新登入，請重試剛才的操作。');return;}}
    S.round=null;S.mode=null;S.target=null;S.draft=null;S.viewRevision=null;S.storageError=false;await loadRounds(true);
  }
  function showSessionLogin(){if(!S.identity||$('session-dialog').open)return;$('session-login').innerHTML=loginForm('session');updateSeats('session');$('session-dialog').showModal();}
  async function loadRounds(auto=false){if(!canLeave())return;S.epoch++;loading('正在讀取你的課堂…');const data=await api('listMyRounds');S.rounds=data.rounds;S.screen='rounds';const active=S.rounds.filter(r=>r.phase!=='closed');if(auto&&active.length===1){await enterRound(active[0].id);return;}renderRounds();}
  function renderRounds(){S.screen='rounds';setView(`<div class="page-heading"><div><p class="eyebrow">MY ART JOURNEY</p><h1>我的<span class="mark">課堂</span></h1><p class="muted">從今天的作品，開始新的發現。</p></div>${button(icon('refresh')+'更新課堂','rounds')}</div><div class="round-grid">${S.rounds.length?S.rounds.map(r=>`<article class="card lesson-card"><img src="${asset(r.plan.reference.image)}" alt="${esc(r.plan.reference.title)}"><div>${tag(r.classId)}${tag(r.phase==='closed'?'已結束・可查看':r.phase==='peer_open'?'同學作品已開放':'正在探索','gold')}<h2>${esc(r.plan.title)}</h2><p class="muted">${esc(r.plan.subtitle)}</p><div class="actions">${button('進入課題 '+icon('arrow'),'enter-round',`data-id="${esc(r.id)}"`,'primary round')}</div></div></article>`).join(''):'<div class="empty"><h2>老師尚未安排課堂</h2><p>稍後可以按「更新課堂」再看看。</p></div>'}</div>`);}
  async function enterRound(id){if(!canLeave())return;S.epoch++;S.draft=null;S.mode=null;S.target=null;S.viewRevision=null;loading();const data=await api('getNotebook',{roundId:id});S.book=data;S.round=data.round;S.screen='lesson';renderLesson();}
  function progressFor(mode){return latest((S.book.assessments||[]).filter(a=>a.mode===mode&&a.status==='submitted')).length>0;}
  function renderLesson(){S.screen='lesson';const r=S.round;setView(`<div class="page-heading"><div><p class="eyebrow">${esc(r.classId)}・${esc(r.plan.medium)}</p><h1>${esc(r.plan.title)}</h1><p class="muted">${esc(r.plan.subtitle)}</p></div>${button(icon('note')+'我的筆記','notebooks')}</div><article class="card lesson-card"><img src="${asset(r.plan.reference.image)}" alt="${esc(r.plan.reference.title)}"><div>${tag(r.phase==='closed'?'課堂已關閉・仍可查看':r.phase==='peer_open'?'互評已開放':'本課正在收集筆記','gold')}<h2>今天，我們留意甚麼？</h2><p>${r.plan.questions.reference.map(q=>tag(q.label)).join('')}</p><p class="small muted">${esc(r.plan.context)}</p></div></article>${r.exempt?'<div class="notice">老師已為你記錄本課豁免；你仍可查看自己的作品與筆記。</div>':''}<div class="activity-list">${r.plan.activities.map((mode,i)=>`<article class="card activity-card"><span class="num">0${i+1}</span><h3>${esc(titleMode(mode))}</h3><p>${mode==='reference'?'從名作中找線索，記下自己的發現。':mode==='self'?'看回自己的創作，說說選擇與效果。':'看看另一位同學的作品，用依據說說。'}</p>${button((mode==='peer'?'更新清單':progressFor(mode)?'繼續查看':'開始探索')+' '+icon('arrow'),mode==='reference'?'reference':mode==='self'?'self':'peer','','primary')}</article>`).join('')}</div><div class="guide-strip">${portrait(r.plan.ks==='ks2')}<div><h3>你可以慢慢看，也可以改變想法。</h3><p class="muted">需要時按「給我提示」。想先向老師說，也可以留下記號。</p></div></div>`);}
  async function refreshBook(){S.book=await api('getNotebook',{roundId:S.round.id});S.round=S.book.round;}
  async function openSubject(mode,target,screen){if(!canLeave())return;S.epoch++;S.draft=null;S.viewRevision=null;loading('正在打開筆記…');await refreshBook();S.mode=mode;S.target=target;S.art=mode==='reference'?null:await api('getArtwork',{roundId:S.round.id,artworkId:target});const records=subjectRecords(),remote=records[records.length-1];const local=readStorage(storageKey());S.conflict=null;
    if(local&&local.responses){S.draft=local;if(remote&&remote.revision>local.baseRevision){if(local.dirty)S.conflict=remote;else S.draft=cleanDraft(remote);}}
    else S.draft=cleanDraft(remote);
    S.step=0;S.screen=screen||(remote||S.draft.dirty?'notebook':'question');if(S.screen==='warmup')S.screen='question';persist();renderStudent();
  }
  function topLine(){return `<div class="lesson-top">${button(icon('back')+'課題','lesson','','quiet')}<span>${esc(S.round.plan.title)}</span><span>${esc(titleMode(S.mode))}</span></div><nav class="stages" aria-label="學習位置"><span class="${S.screen==='question'?'current':''}">指一指・說一說</span><span class="${S.screen==='notebook'?'current':''}">我的筆記</span></nav>`;}
  function artPanel(){const ref=S.round.plan.reference,isRef=S.mode==='reference',src=isRef?asset(ref.image):S.art.imageData,title=isRef?ref.title:S.mode==='self'?'我的作品':'同學作品',editable=S.screen==='question'&&!readonly();let pins=[];
    if(S.draft){if(S.screen==='question')pins=(answer().pins||[]).map((p,i)=>({...p,num:i+1}));else questions().forEach((q,i)=>(S.draft.responses[q.id]&&S.draft.responses[q.id].pins||[]).forEach(p=>pins.push({...p,num:i+1})));}
    return `<section class="art-column"><h2>${esc(title)}</h2>${editable?`<p class="pin-hint" role="note">撳作品標記位置（可選）</p>`:''}<div class="frame"><div class="image-wrap ${editable?'markable':''}" ${editable?'title="撳作品標記位置（可選）"':''}><img id="work-image" src="${src}" alt="${esc(title)}" ${editable?'data-markable="true"':''}>${pins.map(p=>`<span class="pin" style="left:${p.x*100}%;top:${p.y*100}%">${p.num}</span>`).join('')}</div></div><div class="art-meta"><p>${isRef?`${esc(ref.artist)}<br>${esc(ref.date)}`:'每件作品，都有不同的發現。'}</p>${button(icon('expand')+'放大作品','zoom','','round small')}</div>${editable?`<div class="location-controls">${button('整件作品','whole',`aria-pressed="${!!answer().whole}"`)}${button('取消標記','clear-pins')}<label>也可以用文字指出位置<input id="location-input" aria-label="觀察位置" placeholder="例如：嘴角／天空的雲" value="${esc(answer().location)}"></label><span class="muted small">標記不是必做，也可以直接說明。</span></div>`:''}${isRef?`<details class="source-details"><summary>作品資料與圖片來源</summary><p>${esc(ref.credit)}</p><a href="${esc(ref.url)}" target="_blank" rel="noopener">館藏資料 ↗</a><a href="${esc(ref.imageSource)}" target="_blank" rel="noopener">圖片來源 ↗</a></details>`:''}</section>`;
  }
  function companionPrompt(step,total){if(step===0)return '先指一指作品，再說一說你的發現。';if(step===total-1)return '指一指依據，再說清楚你的想法。';return '指着作品說一說，再用自己的話記下來。';}
  function feelingStrip(){const feelings=['平靜','開心','好奇','緊張','難過','未有特別感覺'];return `<div class="feeling-strip" aria-label="第一眼感受（可選）"><span class="feeling-strip-label">第一眼感受（可選）</span><div class="feelings compact">${feelings.map(x=>button(esc(x),'feeling',`data-value="${esc(x)}" aria-pressed="${S.draft.feeling===x}"`)).join('')}</div><label class="field feeling-custom"><span class="sr-only">用自己的詞</span><input id="feeling-input" placeholder="也可以用自己的詞" value="${esc(S.draft.feeling)}" maxlength="80"></label></div>`;}
  function renderStudent(){if(S.conflict){renderConflict();return;}let panel='';const closed=readonly();
    if(S.screen==='warmup'){S.screen='question';S.step=0;}
    if(S.screen==='question'){
      const q=questions()[S.step],a=answer(),prev=S.step>0?(S.draft.responses[questions()[S.step-1].id]||{}).text:'',level=S.draft.hintOpen&&S.draft.hintOpen[q.id],total=questions().length;
      panel=`<div class="companion-note">${portrait(S.round.plan.ks==='ks2')}<p class="speech">${companionPrompt(S.step,total)}</p></div><p class="question-number">${S.step+1} / ${total}・${esc(q.label)}</p><h1 class="question-title">${esc(q.question)}</h1>${S.step===0&&!closed?feelingStrip():''}${prev?`<div class="prior">你剛才說：<br>「${esc(prev)}」</div>`:''}<label class="response-label" for="answer-input">我的回應</label><textarea id="answer-input" class="response-input" placeholder="用自己的話，短詞或短句也可以。" maxlength="3000" ${closed?'readonly':''}>${esc(a.text)}</textarea><div class="support-choices">${button('這裏我需要協助','support','data-value="help" aria-pressed="'+(a.support==='help')+'" '+(closed?'disabled':''))}${button('我想向老師說','support','data-value="oral" aria-pressed="'+(a.support==='oral')+'" '+(closed?'disabled':''))}</div>${a.support?`<p class="small muted">${a.support==='oral'?'已記下待口頭回應；由老師聽過後確認。':'老師會看到這一題需要協助。你仍可以補充想法。'}</p>`:''}${button(icon('help')+'給我提示 '+icon('chevron'),'toggle-hint',`aria-expanded="${Number.isInteger(level)&&level>=0}"`,'help-toggle')}${Number.isInteger(level)&&level>=0?`<div class="hint"><div class="hint-tabs">${['觀察方向','詞彙','句式'].map((x,i)=>button(x,'hint',`data-level="${i}" aria-pressed="${i===level}"`)).join('')}</div><p>${esc(q.hints[level])}</p>${level===0?`<label class="field"><span>我想留意</span><select id="focus-input"><option value="">先自己看看</option>${(S.round.plan.ks==='ks1'?['人物','衣服','背景','其他地方']:['天空','麥田','樹木','其他地方']).map(x=>`<option ${a.focus===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}<p class="small muted">提示幫你開始，答案由你自己決定。</p></div>`:''}<div class="step-footer">${button(icon('back')+'上一步','prev',S.step===0?'disabled':'')}${button(S.step===questions().length-1?'看看我的筆記 '+icon('note'):'下一步 '+icon('arrow'),'next','','primary round')}</div>`;
    }else{
      const records=subjectRecords(),feedback=records.flatMap(r=>r.feedback||[]),current=S.viewRevision||S.draft.baseRevision;
      panel=`<p class="eyebrow">MY LOOKING NOTES</p><h1 class="question-title">我的<span class="mark">看畫筆記</span></h1>${S.viewRevision?`<div class="notice">正在查看第 ${S.viewRevision} 版，內容只供回看。${button('返回最新筆記','latest','','small')}</div>`:closed?'<div class="notice">課堂已關閉，筆記仍可查看。</div>':''}${S.draft.feeling?`<p class="revision-note">第一眼的感受：${esc(S.draft.feeling)}</p>`:''}${questions().map((q,i)=>{const a=S.draft.responses[q.id]||M.emptyAnswer();return `<article class="notebook-card"><header><h3><span class="mark">${i+1} ${esc(q.label)}</span></h3>${!closed?button('修改','edit',`data-index="${i}"`,'small'):''}</header><p class="answer-text">${esc(a.text)||'<span class="muted">尚未留下文字回應</span>'}</p>${a.support?tag(a.support==='oral'?(!S.draft.dirty&&feedback.filter(f=>f.assessmentRevision===current).slice(-1).some(f=>f.reviews[q.id]?.oralNote)?'老師已核實口頭回應':'待口頭回應'):'這裏需要協助','gold'):''}${a.location?`<p class="small muted">觀察位置：${esc(a.location)}</p>`:''}</article>`;}).join('')}${!closed?`<div class="actions">${button(icon('save')+'儲存筆記','save-draft')}${button('交給老師 '+icon('arrow'),'submit','','primary round')}</div>`:''}<p id="save-label" class="save-label"></p>${S.storageError?button('下載本機副本','export'):''}${records.length?`<div class="version-select"><label for="history-version">回看版本</label><select id="history-version"><option value="">最新筆記</option>${records.map(r=>`<option value="${r.revision}" ${S.viewRevision===r.revision?'selected':''}>第 ${r.revision} 版・${r.status==='submitted'?'已交':'草稿'}・${date(r.updatedAt)}</option>`).join('')}</select></div>`:''}${feedback.length?`<h3 style="margin-top:30px">老師給我的回饋</h3>${feedback.map(f=>feedbackHTML(f,current)).join('')}`:''}${S.mode==='self'&&S.book.received.some(x=>x.targetId===S.target)?`<h3>同學看到了甚麼？</h3>${S.book.received.filter(x=>x.targetId===S.target).map(x=>`<section class="feedback"><p class="eyebrow">同學的評賞・第 ${x.revision} 版</p>${S.round.plan.questions.peer.map(q=>`<p><strong>${esc(q.label)}</strong><br>${esc((x.responses[q.id]||{}).text)||'同學正等待老師協助補充。'}</p>`).join('')}</section>`).join('')}`:''}`;
    }
    setView(topLine()+`<div class="work-grid">${artPanel()}<section class="response-panel">${panel}</section></div>`);setSaveLabel();
  }
  function feedbackHTML(f,current){return `<section class="feedback"><h3>老師的觀察與下一步</h3><p class="small muted">對第 ${f.assessmentRevision} 版的回饋${f.assessmentRevision!==current?'・保留原本的觀察':''} · ${date(f.createdAt)}</p>${f.strengths?`<p><strong>已看到的亮點</strong><br>${esc(f.strengths)}</p>`:''}${f.nextStep?`<p><strong>下一步</strong><br>${esc(f.nextStep)}</p>`:''}${Object.entries(f.reviews).map(([id,r])=>{const q=questions().find(x=>x.id===id);return `${r.rating!=='未評閱'?`<p class="small">${esc(q?q.label:id)}：${esc(r.rating)}</p>`:''}${r.oralNote?`<p class="small">老師已聽取口頭回應：${esc(r.oralNote)}</p>`:''}`;}).join('')}</section>`;}
  async function cloudSave(status){if(readonly())return;persist();const payload={roundId:S.round.id,mode:S.mode,targetId:S.target,baseRevision:S.draft.baseRevision,status,responses:M.clone(S.draft.responses),feeling:S.draft.feeling};const fingerprint=JSON.stringify(payload);
    if(!S.draft.pending||S.draft.pending.fingerprint!==fingerprint)S.draft.pending={fingerprint,id:crypto.randomUUID()};persist();const savedDraft=S.draft;
    try{const record=await api('saveAssessment',payload,S.draft.pending.id);savedDraft.baseRevision=record.revision;savedDraft.serverId=record.id;savedDraft.serverStatus=record.status;savedDraft.dirty=JSON.stringify(savedDraft.responses)!==JSON.stringify(payload.responses)||savedDraft.feeling!==payload.feeling;delete savedDraft.pending;persist();await refreshBook();S.screen='notebook';renderStudent();message(status==='submitted'?'已交給老師；需要協助的地方也一併記下。':'筆記已儲存到學校。');}
    catch(e){if(e.code==='VERSION_CONFLICT'){await refreshBook();S.conflict=subjectRecords().slice(-1)[0];renderConflict();}else throw e;}
  }
  function renderConflict(){S.screen='conflict';setView(`<div class="page-heading"><div><p class="eyebrow">你的兩份內容都會保留</p><h1>先看看<span class="mark">不同的版本</span></h1></div></div><div class="notice">學校已有另一份較新的筆記。本機內容仍然保留，請選擇怎樣繼續。</div><div class="conflict-grid"><section><h2>這部裝置的內容</h2><pre>${esc(localSummary(S.draft.responses))}</pre></section><section><h2>學校第 ${S.conflict.revision} 版</h2><pre>${esc(localSummary(S.conflict.responses))}</pre></section></div><div class="actions">${button('採用學校版本','conflict-remote')}${S.round.phase!=='closed'?button('以本機內容另存補充版本','conflict-local','','primary'):''}${button('下載本機副本','export')}</div>`);}
  async function showSelf(){if(!canLeave())return;S.epoch++;S.draft=null;S.mode=null;S.target=null;await refreshBook();S.screen='upload';S.upload=readStorage(uploadKey());renderUpload();}
  function uploadKey(){return 'art-time-capsule-upload:'+M.key(S.identity,S.round.id,'self','pending');}
  function renderUpload(){setView(`<div class="lesson-top">${button(icon('back')+'課題','lesson','','quiet')}<span>${esc(S.round.plan.title)}</span></div><div class="page-heading"><div><p class="eyebrow">MY ARTWORK</p><h1>看回<span class="mark">自己的作品</span></h1><p class="muted">把創作帶進來，說說你的選擇與發現。</p></div></div>${S.round.phase==='collecting'?`<section class="upload-box"><h2>${S.upload?'先確認作品照片':'放進你的作品照片'}</h2><p class="muted">請確保方向正確，作品的細節看得清楚。</p><label class="field"><span class="sr-only">選擇作品照片</span><input id="art-file" type="file" accept="image/jpeg,image/png,image/webp"></label>${S.upload?`<img class="upload-preview" src="${S.upload.imageData}" alt="待確認的作品照片"><div class="actions" style="justify-content:center">${button('向右旋轉','rotate-upload')}${button('確認照片，開始自評 '+icon('arrow'),'confirm-upload','','primary round')}</div>`:''}</section>`:'<div class="notice">本課已停止收集新照片，你仍可查看原有作品。</div>'}<h2 style="margin-top:30px">我已帶來的作品</h2><div class="works-list">${S.book.artworks.length?S.book.artworks.map((w,i)=>button(`作品 ${i+1} · ${date(w.createdAt)}`,'open-self',`data-id="${esc(w.id)}"`)).join(''):'<p class="muted">還未有作品。選好照片後，按確認就可以開始。</p>'}</div>`);}
  async function compressImage(src,rotate=false){const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('讀不到這張圖片，請選 JPEG、PNG 或 WebP 照片。'));i.src=src;});let longest=Math.min(1600,Math.max(img.naturalWidth,img.naturalHeight)),quality=.82,result;
    for(let i=0;i<12;i++){const ratio=longest/Math.max(img.naturalWidth,img.naturalHeight),w=Math.max(1,Math.round(img.naturalWidth*ratio)),h=Math.max(1,Math.round(img.naturalHeight*ratio)),canvas=document.createElement('canvas');canvas.width=rotate?h:w;canvas.height=rotate?w:h;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);if(rotate){ctx.translate(canvas.width,0);ctx.rotate(Math.PI/2);}ctx.drawImage(img,0,0,w,h);result=canvas.toDataURL('image/jpeg',quality);if(atob(result.split(',')[1]).length<=250*1024)return result;if(quality>.48)quality-=.1;else longest*=.8;}
    throw new Error('圖片仍然太大，請裁走照片中作品以外的部分再試。');
  }
  async function selectFile(file){if(!file)return;const epoch=S.epoch;if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('請選 JPEG、PNG 或 WebP 圖片。');const url=URL.createObjectURL(file);let data;try{data=await compressImage(url);}finally{URL.revokeObjectURL(url);}if(epoch!==S.epoch)return;S.upload={imageData:data,requestId:crypto.randomUUID()};try{localStorage.setItem(uploadKey(),JSON.stringify(S.upload));}catch(_){message('照片暫時只保留在此頁，請確認後儲存到學校。',true);}renderUpload();}
  async function confirmUpload(){const data=await api('uploadArtwork',{roundId:S.round.id,imageBase64:S.upload.imageData,imageMime:'image/jpeg'},S.upload.requestId);localStorage.removeItem(uploadKey());S.upload=null;await openSubject('self',data.artworkId,'question');}
  async function showPeer(){if(!canLeave())return;const data=await api('listPeerWorks',{roundId:S.round.id});if(!data.items.length){message('老師未為你安排本課互評作品。');return;}await openSubject('peer',data.items[0].id);}
  async function notebooks(){if(!canLeave())return;S.epoch++;S.draft=null;S.mode=null;S.target=null;loading();if(!S.round){await loadRounds();return;}await refreshBook();S.screen='notebooks';const entries=latest(S.book.assessments);try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key.startsWith('art-time-capsule-v2:'))continue;const parts=JSON.parse(key.slice('art-time-capsule-v2:'.length));if(parts[0]!==S.identity.schoolYear||parts[1]!==S.identity.classId||parts[2]!==S.identity.studentId||parts[3]!==S.round.id)continue;const draft=readStorage(key);if(!draft?.dirty)continue;const entry=entries.find(a=>a.mode===parts[4]&&a.targetId===parts[5]);if(entry)entry.localOnly=true;else entries.push({id:key,mode:parts[4],targetId:parts[5],revision:draft.baseRevision,updatedAt:draft.modifiedAt,localOnly:true});}}catch(_){}setView(`<div class="page-heading"><div><p class="eyebrow">MY NOTEBOOK</p><h1>我的<span class="mark">筆記</span></h1><p class="muted">${esc(S.round.plan.title)}・每次發現，都值得留下。</p></div>${button(icon('refresh')+'更新筆記','notebooks')}</div><div class="stack">${entries.length?entries.map(a=>{const all=S.book.assessments.filter(x=>x.id===a.id),fbs=all.flatMap(x=>x.feedback||[]);return `<article class="card"><div class="page-heading" style="margin:0"><div>${tag(titleMode(a.mode))}${tag(a.localOnly?'有本機未儲存內容':a.status==='submitted'?'已交給老師':'已儲存到學校','gold')}<h2>${esc(S.round.plan.title)}</h2><p class="small muted">第 ${a.revision} 版 · ${date(a.updatedAt)}${fbs.length?' · 有老師回饋':''}${a.mode==='self'&&S.book.received.some(x=>x.targetId===a.targetId)?' · 收到同學評語':''}</p></div>${button('打開筆記 '+icon('arrow'),'open-note',`data-mode="${a.mode}" data-id="${esc(a.targetId)}"`,'primary round')}</div></article>`;}).join(''):'<div class="empty"><h2>第一份筆記，等你開始。</h2><p>開始活動留下回應後，便會出現在這裏。</p></div>'}</div><div class="actions" style="margin-top:28px">${button('返回本課','lesson')}${button('查看舊版記錄','legacy','','quiet')}</div>`);}
  async function legacy(){const list=await api('legacyRounds');setView(`<div class="page-heading"><div><h1>舊版記錄</h1><p class="muted">保留原有五步內容，只供查看，不換算新評級。</p></div>${button('返回筆記','notebooks')}</div><div class="stack">${list.rounds.length?list.rounds.map(r=>button(esc(r.topicId),'legacy-open',`data-id="${esc(r.id)}"`)).join(''):'<p class="empty">這個身份沒有可讀取的舊版課堂。</p>'}</div>`);}
  async function legacyOpen(id){let offset=0,items=[];do{const page=await api('legacyOwnWorks',{roundId:id,offset});items.push(...page.items);offset=page.nextOffset;}while(offset!=null);setView(`<div class="page-heading"><h1>舊版作品與自評</h1>${button('返回','legacy')}</div>${items.map(w=>`<article class="card" style="margin-bottom:20px"><img src="${w.imageData}" alt="舊版作品" style="max-height:300px;margin:auto"><p class="notice">原有五步紀錄・只讀</p>${Object.entries(w.assessment&&w.assessment.steps||{}).map(([key,a])=>`<p><strong>${esc({feel:'整體感受',describe:'描述',form:'分析',meaning:'理解',judge:'評價'}[key]||key)}</strong>：${esc(a.open||(a.scaffold||[]).join(' '))}</p>`).join('')}</article>`).join('')||'<p class="empty">沒有已交的舊版作品。</p>'}`);}
  async function teacherEntry(){if(!canLeave())return;S.epoch++;S.token=null;S.identity=null;S.draft=null;S.round=null;S.mode=null;S.target=null;S.viewRevision=null;loading('正在核對教師權限…');if(window.VA_PREVIEW)await fetch('/preview/identity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:'teacher'})});try{S.teacher=await api('teacherContext');await teacherHome();}catch(e){S.teacher=null;setView(`<div class="empty"><h1>未能開啟教師畫面</h1><p>${esc(e.message)}</p>${button('返回學生入口','logout')}</div>`);}}
  async function teacherHome(){if(!canLeave())return;S.epoch++;loading('正在讀取你的班別…');const data=await api('teacherRounds');S.teacherRounds=data.rounds;S.screen='teacher-home';S.draft=null;setView(`<div class="page-heading"><div><p class="eyebrow">TEACHER'S STUDIO</p><h1>看見每一份<span class="mark">發現</span></h1><p class="muted">從學生的原話，找到下一步的引導。</p></div>${button('安排新的課堂 '+icon('arrow'),'teacher-create','','primary round')}</div><div class="round-grid">${data.rounds.length?data.rounds.map(r=>`<article class="card lesson-card"><img src="${asset(r.plan.reference.image)}" alt="${esc(r.plan.reference.title)}"><div>${tag(r.classId)}${tag(r.phase==='closed'?'已關閉':r.phase==='peer_open'?'互評已開放':'收集作品與筆記','gold')}<h2>${esc(r.plan.title)}</h2><p class="muted small">${r.progress.filter(p=>p.selfSubmitted&&!p.exempt).length} 份自評已交・${r.members.filter(m=>!m.exempt).length} 位應參與學生</p><div class="actions">${button('查看課堂 '+icon('arrow'),'teacher-round',`data-id="${esc(r.id)}"`,'primary round')}</div></div></article>`).join(''):'<div class="empty"><h2>先安排第一個評賞課堂。</h2><p>選擇班別及課題，便可預覽學生的引導問題。</p></div>'}</div>`);}
  function teacherCreate(){S.screen='teacher-create';const classes=S.teacher.classes.filter(c=>M.templates[c.grade]&&c.studentIds.length);setView(`<div class="page-heading"><div><p class="eyebrow">A NEW ART CONVERSATION</p><h1>安排<span class="mark">評賞課堂</span></h1><p class="muted">先選本課重點，再看看學生會收到的問題。</p></div>${button('返回班別','teacher-home')}</div>${classes.length?`<form id="create-round-form" data-form="create-round" class="two-col"><section class="card teacher-form"><label class="field"><span>班別</span><select name="classId" id="setup-class">${classes.map(c=>`<option value="${esc(c.classId)}">${esc(c.classId)}</option>`).join('')}</select></label><div id="setup-template"></div><div><h3>本課活動</h3><div class="check-list">${Object.entries(M.modes).map(([mode,label])=>`<label><input type="checkbox" name="activities" value="${mode}" checked>${esc(label)}</label>`).join('')}</div><p class="small muted">互評需要配合自評；每人評賞一件同學作品。</p></div><button type="submit" class="primary round">建立並開放課堂 ${icon('arrow')}</button><p class="small muted">開放後，本課問題會固定，學生中途不會遇到要求改變。</p></section><section><h2 style="margin-bottom:18px">學生問題預覽</h2><div id="setup-preview" class="stack"></div></section></form>`:'<div class="notice">你所屬班別暫未有小二或小五試用課題。請先核對教師班別設定。</div>'}`);if(classes.length)updateTemplate();}
  function updateTemplate(){const cls=S.teacher.classes.find(c=>c.classId===$('setup-class').value),t=M.templates[cls.grade];$('setup-template').innerHTML=`<input type="hidden" name="templateId" value="${t.id}"><h2>${esc(t.title)}</h2><p class="small muted">${esc(t.medium)}・${esc(t.subtitle)}</p><h3 style="margin-top:20px">本課評賞重點</h3><div class="check-list">${t.questions.reference.map(q=>`<label><input type="checkbox" name="objectiveIds" value="${q.id}" checked>${esc(q.label)}</label>`).join('')}</div>`;updateTemplatePreview();}
  function updateTemplatePreview(){const form=$('create-round-form'),fd=new FormData(form),self=form.querySelector('[name=activities][value=self]'),peer=form.querySelector('[name=activities][value=peer]');if(!self.checked){peer.checked=false;peer.disabled=true;}else peer.disabled=false;const current=new FormData(form);try{const p=M.makePlan(current.get('templateId'),current.getAll('objectiveIds'),current.getAll('activities'));$('setup-preview').innerHTML=p.activities.map(mode=>`<section class="template-preview"><h3>${esc(titleMode(mode))}</h3><ol>${p.questions[mode].map(q=>`<li>${esc(q.question)}</li>`).join('')}</ol></section>`).join('');}catch(e){$('setup-preview').innerHTML=`<div class="notice">${esc(e.message)}</div>`;}}
  async function createRound(form){const fd=new FormData(form),payload={classId:fd.get('classId'),templateId:fd.get('templateId'),objectiveIds:fd.getAll('objectiveIds'),activities:fd.getAll('activities')};const fingerprint=JSON.stringify(payload);if(form.dataset.fingerprint!==fingerprint){form.dataset.fingerprint=fingerprint;form.dataset.requestId=crypto.randomUUID();}const result=await api('createRound',payload,form.dataset.requestId);await teacherRound(result.id);message('課堂已開放，學生可以開始探索。');}
  async function teacherRound(id){if(!canLeave())return;S.epoch++;S.draft=null;S.mode=null;S.target=null;loading();S.overview=await api('teacherOverview',{roundId:id});S.round=S.overview.round;S.screen='teacher-round';renderTeacherRound();}
  function renderTeacherRound(){const d=S.overview,r=d.round,entries=d.entries,unreviewed=entries.filter(a=>!a.feedback.length),help=entries.filter(a=>a.needsHelp&&!a.feedback.length),oral=entries.filter(a=>a.pendingOral);const filtered=S.filter==='all'?entries:S.filter==='unreviewed'?unreviewed:S.filter==='help'?help:oral;
    setView(`<div class="page-heading"><div><p class="eyebrow">${esc(r.classId)}・教師課堂</p><h1>${esc(r.plan.title)}</h1><p class="muted">${r.phase==='closed'?'課堂已關閉；學生仍可回看，你仍可留下回饋。':r.phase==='peer_open'?'互評配對已固定；學生按更新清單後開始。':'查看回應，再安排個別支援與互評。'}</p></div>${button(icon('refresh')+'更新課堂','teacher-round',`data-id="${esc(r.id)}"`)}</div><div class="stats"><div class="stat"><strong>${entries.length}</strong><span>已交評賞記錄</span></div><div class="stat"><strong>${unreviewed.length}</strong><span>待評閱記錄</span></div><div class="stat"><strong>${help.length}</strong><span>待協助記錄</span></div><div class="stat"><strong>${oral.length}</strong><span>待口頭核實記錄</span></div></div><div class="actions">${r.phase==='collecting'&&r.plan.activities.includes('peer')?button('核對並開放互評','open-peer','','primary'):''}${r.phase==='collecting'?button('缺席／豁免','exemptions'):''}${r.phase!=='closed'?button('關閉課堂','close-round'):''}</div><details class="card" style="margin-top:24px"><summary>查看全班收集狀態</summary><table class="teacher-summary"><thead><tr><th>學號</th><th>名作欣賞</th><th>自評</th><th>互評</th><th>參與狀態</th></tr></thead><tbody>${d.progress.map(p=>`<tr><td>${esc(p.studentId)}</td><td>${p.referenceSubmitted?'已交':'—'}</td><td>${p.selfSubmitted?'已交':'—'}</td><td>${p.peerSubmitted?'已交':'—'}</td><td>${p.exempt?'已豁免':'應參與'}</td></tr>`).join('')}</tbody></table><p class="small muted">已交表示收到回應或支援請求，不代表已掌握能力。</p></details><div class="filters">${[['all','全部'],['unreviewed','待評閱'],['help','需要協助'],['oral','待口頭核實']].map(([value,label])=>button(label,'filter',`data-value="${value}" aria-pressed="${S.filter===value}"`)).join('')}</div><section>${filtered.length?filtered.map(a=>`<article class="review-row"><span class="seat">${esc(a.studentId)}</span><div class="review-content"><h3>${esc(titleMode(a.mode))}</h3><p>第 ${a.revision} 版 · ${date(a.updatedAt)}</p>${!a.feedback.length?tag('未評閱'):tag('已回饋')}${a.needsHelp?tag('需要協助','gold'):''}${a.pendingOral?tag('待口頭核實','gold'):''}</div>${button('查看回應','teacher-detail',`data-id="${esc(a.id)}" data-revision="${a.revision}"`,'primary')}</article>`).join(''):'<div class="empty">暫時沒有這類記錄。</div>'}</section>`);
  }
  function showExemptions(){setView(`<div class="page-heading"><div><h1>本課缺席與豁免</h1><p class="muted">保留學生的查看權限；已豁免者不加入互評配對。</p></div>${button('返回課堂','teacher-round',`data-id="${esc(S.round.id)}"`)}</div><form data-form="exemptions" class="card"><div>${S.round.members.map(m=>`<div class="exemption-row"><label><input type="checkbox" name="exempt" value="${esc(m.studentId)}" ${m.exempt?'checked':''}>${esc(m.studentId)} 號</label><input type="text" name="reason-${esc(m.studentId)}" aria-label="${esc(m.studentId)}號豁免原因" placeholder="例如：本課缺席" maxlength="300" value="${esc(m.reason)}" ${!m.exempt?'disabled':''}></div>`).join('')}</div><button class="primary" type="submit" style="margin-top:24px">儲存豁免記錄</button></form>`);}
  async function changeRound(payload){const r=await api('updateRound',{roundId:S.round.id,baseRevision:S.round.revision,...payload},crypto.randomUUID());await teacherRound(r.id);}
  function openPeerConfirm(){const ready=S.overview.progress.filter(m=>!m.exempt),missing=ready.filter(m=>!m.selfSubmitted);if(missing.length){message('未交作品及自評的學號：'+missing.map(m=>m.studentId).join('、')+'。請先核對或記錄豁免。',true);return;}if(ready.length<2){message('至少需要兩名已交作品及自評的學生。',true);return;}setView(`<div class="page-heading"><div><h1>準備開放互評</h1><p class="muted">${ready.length} 位學生已交作品及自評，每人會配到一件同學作品。</p></div></div><div class="card"><h2>讓每件作品，都有人細看。</h2><p style="margin-top:15px">按班號循環配對，排除自己及已豁免者。開放後，配對及作品照片會固定；學生仍可補充評賞文字。</p><p class="small muted">已交不代表已掌握。需要協助及待口頭回應的記錄仍會保留。</p><div class="actions" style="margin-top:22px">${button('返回核對','teacher-round',`data-id="${esc(S.round.id)}"`)}${button('開放互評','confirm-open-peer','','primary')}</div></div>`);}
  function closeRoundConfirm(){setView(`<div class="page-heading"><h1>關閉這個課堂？</h1></div><div class="card"><p>關閉後，學生仍可查看作品、筆記及回饋，但不能再上傳或修改。請先確認課堂活動已結束。</p><div class="actions" style="margin-top:22px">${button('返回課堂','teacher-round',`data-id="${esc(S.round.id)}"`)}${button('確認關閉課堂','confirm-close','','primary')}</div></div>`);}
  async function teacherDetail(id,revision){if(!canLeave())return;S.epoch++;loading();S.detail=await api('teacherDetail',{roundId:S.round.id,assessmentId:id,revision:Number(revision)});S.round=S.detail.round;S.mode=S.detail.assessment.mode;S.target=S.detail.assessment.targetId;S.art=S.detail.artwork;S.draft=cleanDraft(S.detail.assessment);S.viewRevision=null;S.screen='teacher-detail';renderTeacherDetail();}
  function renderTeacherDetail(){const d=S.detail,a=d.assessment,f=d.feedback.filter(f=>f.assessmentRevision===a.revision).slice(-1)[0],reviews=f?f.reviews:{};setView(`<div class="lesson-top">${button(icon('back')+'課堂','teacher-round',`data-id="${esc(S.round.id)}"`,'quiet')}<span>${esc(S.round.classId)}・${esc(a.studentId)} 號</span><span>${esc(titleMode(a.mode))}</span></div><div class="work-grid">${artPanel()}<section class="response-panel"><p class="eyebrow">從原話，看見學習</p><h1 class="question-title">觀察與<span class="mark">回饋</span></h1><div class="version-select"><label for="teacher-version">學生回應</label><select id="teacher-version">${d.history.map(x=>`<option value="${x.revision}" ${x.revision===a.revision?'selected':''}>第 ${x.revision} 版 · ${date(x.updatedAt)}</option>`).join('')}</select></div><form data-form="feedback" id="feedback-form">${S.round.plan.questions[a.mode].map((q,i)=>{const response=a.responses[q.id],review=reviews[q.id]||{};return `<section class="review-answer"><h3>${i+1} ${esc(q.label)}</h3><p class="small muted">${esc(q.question)}</p><blockquote>${esc(response.text)||'未留下文字回應'}</blockquote>${response.support?tag(response.support==='oral'?(review.oralNote?'老師已核實口頭回應':'待口頭回應'):'曾要求協助','gold'):''}<p class="small muted">已開啟提示：${response.hintsUsed.length?response.hintsUsed.map(i=>['觀察方向','詞彙','句式'][i]).join('、'):'沒有記錄'}${response.focus?' · 觀察方向：'+esc(response.focus):''}${response.location?' · 位置：'+esc(response.location):''}</p><label class="field"><span>老師的觀察（不換算總分）</span><select name="rating-${q.id}">${M.ratings.map(x=>`<option ${review.rating===x?'selected':''}>${x}</option>`).join('')}</select></label>${response.support==='oral'?`<label class="field"><span>已聽取口頭回應：記下學生實際說出的重點</span><textarea name="oral-${q.id}" maxlength="1000" placeholder="未聽取時請保持空白。">${esc(review.oralNote||'')}</textarea></label>`:''}</section>`;}).join('')}<label class="field" style="margin-top:24px"><span>已看到的亮點</span><textarea name="strengths" maxlength="1500" placeholder="指出學生已做到的具體地方。">${esc(f&&f.strengths||'')}</textarea></label><label class="field" style="margin-top:20px"><span>下一步</span><textarea name="nextStep" maxlength="1500" placeholder="一個清楚、可以回到作品嘗試的建議。">${esc(f&&f.nextStep||'')}</textarea></label><p class="small muted" style="margin:16px 0">這次回饋會連到第 ${a.revision} 版，原有意見會保留。</p><button type="submit" class="primary round">儲存回饋 ${icon('arrow')}</button></form>${d.feedback.length?`<details class="source-details" style="margin-top:24px"><summary>查看回饋歷程（${d.feedback.length}）</summary>${d.feedback.map(x=>feedbackHTML(x,a.revision)).join('')}</details>`:''}</section></div>`);}
  async function saveFeedback(form){const fd=new FormData(form),reviews={};questions().forEach(q=>reviews[q.id]={rating:fd.get('rating-'+q.id),oralNote:fd.get('oral-'+q.id)||''});const payload={roundId:S.round.id,assessmentId:S.detail.assessment.id,assessmentRevision:S.detail.assessment.revision,reviews,strengths:fd.get('strengths'),nextStep:fd.get('nextStep')};const fingerprint=JSON.stringify(payload);if(form.dataset.fingerprint!==fingerprint){form.dataset.fingerprint=fingerprint;form.dataset.requestId=crypto.randomUUID();}await api('saveFeedback',payload,form.dataset.requestId);S.feedbackDirty=false;await teacherDetail(payload.assessmentId,payload.assessmentRevision);message('回饋已儲存，學生可以在筆記中查看。');}
  async function logout(){if(!canLeave())return;S.epoch++;Object.assign(S,{identity:null,token:null,teacher:null,round:null,book:null,mode:null,target:null,draft:null,art:null,viewRevision:null,feedbackDirty:false,storageError:false,conflict:null});if(window.VA_PREVIEW)await fetch('/preview/identity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:'student'})});await boot();}
  function zoom(){const img=$('work-image');if(!img)return;$('dialog-image').src=img.src;$('dialog-image').alt=img.alt;$('dialog-title').textContent=img.alt;$('art-dialog').showModal();}
  async function action(name,el){switch(name){
    case'boot':return boot();case'logout':return logout();case'rounds':return loadRounds();case'enter-round':return enterRound(el.dataset.id);case'lesson':if(canLeave()){S.viewRevision=null;S.screen='lesson';renderLesson();}return;
    case'reference':return openSubject('reference',S.round.plan.reference.id);case'self':return showSelf();case'peer':return showPeer();case'open-self':return openSubject('self',el.dataset.id);case'open-note':return openSubject(el.dataset.mode,el.dataset.id,'notebook');case'notebooks':return notebooks();case'zoom':return zoom();case'export':return exportLocal();
    case'feeling':S.draft.feeling=S.draft.feeling===el.dataset.value?'':el.dataset.value;changed();return renderStudent();
    case'begin':S.screen='question';S.step=0;return renderStudent(); // legacy warmup entry → same question flow
    case'prev':if(!persist())return;S.step=Math.max(0,S.step-1);return renderStudent();
    case'next':if(!persist())return;if(S.step<questions().length-1)S.step++;else S.screen='notebook';renderStudent();return;
    case'edit':S.step=Number(el.dataset.index);S.screen='question';return renderStudent();
    case'support':answer().support=answer().support===el.dataset.value?'':el.dataset.value;changed();return renderStudent();
    case'whole':answer().whole=!answer().whole;if(answer().whole)answer().pins=[];changed();return refreshPinsDom();
    case'clear-pins':answer().pins=[];answer().whole=false;changed();return refreshPinsDom();
    case'toggle-hint':{const id=questions()[S.step].id;S.draft.hintOpen=S.draft.hintOpen||{};if(S.draft.hintOpen[id]>=0)S.draft.hintOpen[id]=-1;else{S.draft.hintOpen[id]=0;if(!answer().hintsUsed.includes(0))answer().hintsUsed.push(0);}changed();return renderStudent();}
    case'hint':{const level=Number(el.dataset.level);S.draft.hintOpen[questions()[S.step].id]=level;if(!answer().hintsUsed.includes(level))answer().hintsUsed.push(level);changed();return renderStudent();}
    case'save-draft':return cloudSave('draft');case'submit':return cloudSave('submitted');
    case'conflict-remote':S.draft=cleanDraft(S.conflict);S.conflict=null;S.screen='notebook';persist();return renderStudent();
    case'conflict-local':S.draft.baseRevision=S.conflict.revision;S.conflict=null;delete S.draft.pending;S.draft.dirty=true;persist();return cloudSave('draft');
    case'latest':return openSubject(S.mode,S.target,'notebook');
    case'confirm-upload':return confirmUpload();case'rotate-upload':S.upload.imageData=await compressImage(S.upload.imageData,true);S.upload.requestId=crypto.randomUUID();try{localStorage.setItem(uploadKey(),JSON.stringify(S.upload));}catch(_){}return renderUpload();
    case'legacy':return legacy();case'legacy-open':return legacyOpen(el.dataset.id);
    case'teacher-home':return teacherHome();case'teacher-create':return teacherCreate();case'teacher-round':return teacherRound(el.dataset.id);case'filter':S.filter=el.dataset.value;return renderTeacherRound();case'exemptions':return showExemptions();case'open-peer':return openPeerConfirm();case'confirm-open-peer':return changeRound({phase:'peer_open'});case'close-round':return closeRoundConfirm();case'confirm-close':return changeRound({phase:'closed'});case'teacher-detail':return teacherDetail(el.dataset.id,el.dataset.revision);
  }}
  function refreshPinsDom(){const wrap=document.querySelector('.image-wrap');if(!wrap||S.screen!=='question'){const y=window.scrollY;renderStudent();requestAnimationFrame(()=>window.scrollTo(0,y));return;}wrap.querySelectorAll('.pin').forEach(el=>el.remove());(answer().pins||[]).forEach((p,i)=>{const span=document.createElement('span');span.className='pin';span.style.left=(p.x*100)+'%';span.style.top=(p.y*100)+'%';span.textContent=String(i+1);wrap.appendChild(span);});const wholeBtn=document.querySelector('button[data-action="whole"]');if(wholeBtn)wholeBtn.setAttribute('aria-pressed',answer().whole?'true':'false');}
  let _pinGuard=0,_pinStart=null;
  function addPinAt(clientX,clientY){if(S.screen!=='question'||readonly()||!S.draft)return;const img=document.getElementById('work-image');const wrap=document.querySelector('.image-wrap.markable');if(!img||!wrap)return;const a=answer();if(a.pins.length>=8){message('可以先取消部分標記，再選其他位置。');return;}const rect=img.getBoundingClientRect();if(!rect.width||!rect.height)return;if(clientX<rect.left||clientX>rect.right||clientY<rect.top||clientY>rect.bottom)return;const x=Math.max(0,Math.min(1,(clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(clientY-rect.top)/rect.height));a.pins.push({x,y});a.whole=false;changed();refreshPinsDom();}
  document.addEventListener('click',e=>{const el=e.target.closest('button[data-action]');if(el)act(()=>action(el.dataset.action,el),el);});
  document.addEventListener('pointerdown',e=>{if(e.target.closest('.image-wrap.markable'))_pinStart={x:e.clientX,y:e.clientY};else _pinStart=null;});
  document.addEventListener('pointerup',e=>{const wrap=e.target.closest('.image-wrap.markable');if(!wrap)return;if(e.pointerType==='mouse'&&e.button!==0)return;if(_pinStart&&Math.hypot(e.clientX-_pinStart.x,e.clientY-_pinStart.y)>14){_pinStart=null;return;}_pinStart=null;const now=Date.now();if(now-_pinGuard<80)return;_pinGuard=now;addPinAt(e.clientX,e.clientY);});
  document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();act(async()=>{switch(form.dataset.form){case'login':return login(form.dataset.prefix);case'create-round':return createRound(form);case'feedback':return saveFeedback(form);case'exemptions':{const fd=new FormData(form);return changeRound({exemptions:fd.getAll('exempt').map(id=>({studentId:id,reason:fd.get('reason-'+id)}))});}}},e.submitter);});
  document.addEventListener('input',e=>{if(e.target.id==='answer-input'){answer().text=e.target.value;changed();}if(e.target.id==='location-input'){answer().location=e.target.value;changed();}if(e.target.id==='feeling-input'){S.draft.feeling=e.target.value;changed();}if(e.target.closest('#feedback-form'))S.feedbackDirty=true;});
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='login-class')updateSeats(el.dataset.prefix);if(el.id==='focus-input'){answer().focus=el.value;changed();}if(el.id==='art-file')act(()=>selectFile(el.files[0]));if(el.id==='setup-class')updateTemplate();else if(el.closest('#create-round-form'))updateTemplatePreview();if(el.id==='history-version'){if(!el.value)act(()=>openSubject(S.mode,S.target,'notebook'));else{persist();S.viewRevision=Number(el.value);S.draft=cleanDraft(subjectRecords().find(x=>x.revision===S.viewRevision));renderStudent();}}if(el.id==='teacher-version')act(()=>teacherDetail(S.detail.assessment.id,Number(el.value)));if(el.name==='exempt'){const input=el.closest('form').querySelector(`[name="reason-${el.value}"]`);input.disabled=!el.checked;}});
  document.addEventListener('focusin',e=>{if(e.target.matches('#answer-input,#location-input'))document.body.classList.add('typing');});
  document.addEventListener('focusout',e=>{if(e.target.matches('#answer-input,#location-input'))setTimeout(()=>{if(!document.activeElement.matches('#answer-input,#location-input'))document.body.classList.remove('typing');},0);});
  window.addEventListener('beforeunload',e=>{if(S.storageError||S.feedbackDirty){e.preventDefault();e.returnValue='';}});
  $('teacher-entry').onclick=()=>act(teacherEntry,$('teacher-entry'));
  $('brand-home').onclick=e=>{e.preventDefault();act(()=>S.teacher?teacherHome():S.identity?loadRounds():boot());};
  $('close-art').onclick=()=>$('art-dialog').close();
  $('session-dialog').addEventListener('cancel',e=>e.preventDefault());
  boot();
})();
